import antlr4 from 'antlr4';
import GraphQLV2Lexer from './graphqlv2/GraphQLV2Lexer.js';
import GraphQLV2Parser from './graphqlv2/GraphQLV2Parser.js';
import GraphQLV2Listener from './graphqlv2/GraphQLV2Listener.js';

export class GraphqlV2ASTBuilderCB extends GraphQLV2Listener {

    visitTerminal(node) {
        this.cb.visitTerminal(node, this.parser)
    }

    visitErrorNode(node) {
        this.cb.visitErrorNode(node, this.parser)
    }

    enterEveryRule(node) {
        this.cb.enterEveryRule(node, this.parser)
    }

    exitEveryRule(node) {
        this.cb.exitEveryRule()
    }

    run(input, cb, errorListener) {
        this.cb = cb;
        const chars = new antlr4.InputStream(input);
        const lexer = new GraphQLV2Lexer(chars);
        lexer.removeErrorListeners();
        lexer.addErrorListener(errorListener);
        const tokens = new antlr4.CommonTokenStream(lexer);
        const parser = new GraphQLV2Parser(tokens);
        parser.removeErrorListeners();
        parser.addErrorListener(errorListener);
        this.parser = parser
        this.parser.buildParseTrees = true;
        const tree = this.parser.document();
        antlr4.tree.ParseTreeWalker.DEFAULT.walk(this, tree);
    }
}
